#' Isotope pattern envelope calculation
#' 
#' Convolutes an isotope pattern from isopattern with a peak shape function (Gaussian or Cauchy-Lorentz function) 
#' to its theoretical envelope (profile), at a given measurement resolution. 
#' The envelope is represented by sticks, i.e. measurement abundances at discrete m/z intervals.
#' 
#' @param pattern List of isotope pattern(s) as generated by isopattern.
#' @param ppm Should stick discretization be set in ppm (TRUE) or absolute m/z (FALSE)?
#'   Only checked if dmz is not set to "get"; check details section.
#' @param dmz Stick discretization. Set to "get" to derive discretization from argument resolution or set a numerical value
#'   in combination with ppm to use as ppm or absolute m/z.
#' @param frac Used if dmz is set to "get".
#' @param env Peak shape function; either "Gaussian" or "CauchyLorentz".
#' @param resolution Single resolution value or vector of resolutions with length equal to the number of entries in list pattern.
#' @param plotit Should results be plotted, TRUE/FALSE?
#' @param verbose Verbose, TRUE/FALSE?
#' 
#' @details
#' The theoretical profiles are represented by sticks, i.e. abundances at discrete m/z intervals.
#' While the profile width is set by argument resolution, the mass discretization between adjacent sticks can be set in two different ways.
#' 
#' On the one hand, discretization can be given as a numerical value, either in ppm or absolute m/z. 
#' To do so, set argument dmz to a numerical value and specify with argument ppm if this value is stating the discretization in ppm or 
#' as absolute m/z.
#' 
#' On the other hand, discretization can be derived from the measurement resolution (R) set by
#' argument resolution. To do so, set dmz to "get", which leads to argument ppm being ignored. 
#' In this case, the stick discretization is retrieved from (dm/z)*frac, with (dm/z) = (m/z)/R = peak width at half maximum.
#' 
#' @return List of envelope profiles with the same length as the input list pattern:
#' Each list element contains a data frame with 2 columns:
#' \item{m/z}{m/z values of the sticks comprising the profile}
#' \item{abundance}{Abundance values of the sticks comprising the profile}
#' 
#' @author Martin Loos, Christian Gerber
#' 
#' @seealso isopattern, vdetect
#' 
#' @examples
#' data(isotopes)
#' data(chemforms)
#' chemforms <- chemforms[1:5]
#' 
#' pattern <- isopattern(
#'   isotopes,
#'   chemforms,
#'   threshold=0.1,
#'   plotit=TRUE,
#'   charge=FALSE,
#'   emass=0.00054858,
#'   algo=2
#' )
#' 
#' profiles <- envelope(
#'     pattern,
#'     ppm=FALSE,
#'     dmz=0.0001,   
#'     frac=1/4,
#'     env="Gaussian",
#'     resolution=1E6,
#'     plotit=TRUE
#' )
#' 
#' @export
envelope <-
function(
    pattern,
    ppm=FALSE,
    dmz="get",   # retrieve dm from R=m/dm
    frac=1/4,
    env="Gaussian",
    resolution=5E5,
    plotit=FALSE,
	verbose = TRUE
){

    ############################################################################
    # (1) issue warnings #######################################################
    if((length(resolution)!=length(pattern)) & length(resolution)>1) stop("length of resolution does not match length of pattern list!\n")
    if(ppm==TRUE & dmz=="get") stop("\n WARNING: ppm=TRUE -> dmz must be numerical!\n")
    if(ppm==TRUE & dmz<0) stop("\n WARNING: ppm=TRUE -> dmz must be >0\n")
    if(dmz=="get") if(any(resolution<1))stop("WARNING: invalid resolution!\n")
    if(env!="Gaussian" & env!="CauchyLorentz")stop("WARNING: invalid env argument\n")
    if(ppm!=FALSE & dmz=="get" & frac>1) stop("WARNING: invalid frac argument\n")
    if(ppm!=FALSE & dmz=="get" & frac<0) stop("WARNING: invalid frac argument\n")    
    if(is.list(pattern)==FALSE) stop("WARNING: pattern must be a list\n")
    if(length(pattern[[1]])<3 || !all(colnames(pattern[[1]])[1:2] == c("m/z", "abundance"))) stop("WARNING: is list, but has invalid entries\n")
    if(ppm!="TRUE"&ppm!="FALSE") stop("WARNING: ppm invalid\n")
    if(plotit!="TRUE"&plotit!="FALSE") stop("WARNING: plotit invalid. TRUE, FALSE.\n")
	if(!is.logical(verbose)) stop("invalid verbose")
    options(digits=10);
    ############################################################################
    # (2) create stick masses ##################################################
    if(verbose) message("Calculate profiles ...")
    if(env=="Gaussian"){
		type1=0
    }else{
		type1=1
    }
    if(length(resolution)!=length(pattern)){
		resolution<-rep(resolution,length(pattern))
    }
    profiles<-list(0)
    extend<-c(0.5);
    for(i in 1:length(pattern)){
        m<-pattern[[i]][,1]   
        a<-pattern[[i]][,2]
        if(ppm==TRUE){
            traceit<-.Call("iso_ppm_Call",
				as.double((min(m)-extend)),
                as.double((max(m)+extend)),
                as.double(dmz),
				PACKAGE="enviPat"
            )
        }else{
			if(dmz!="get"){
				traceit<-seq(min(m)-extend,max(m)+extend,dmz);
			}else{
				dmz2<-c(mean(m)/resolution[i]);
				traceit<-seq(min(m)-1,max(m)+extend,dmz2*frac);
			}          
        }
        # m:     double array of the isotope pattern mass
        # a:     double array of the isotope pattern abundance
        # trace:   double array profile masses
        # resolution: FWHM with R=m/dm
        # type:   Gaussian=0 // Cauchy-Lorentz=1 
        # threshold: threshold value to skip redundant calculation over all mass peaks
        #              if = 0 -> dynamic
		out <- .Call("iso_profile_with_trace_Call", 
			type1 = as.integer(type1),
			f1 = as.double(m),
			a1 = as.double(a),
			tr1 = as.double(traceit),
			r1 = as.integer(resolution[i]),
			t1 = as.double(0),
            filter = as.integer(1),
			PACKAGE="enviPat"
		)
		if(length(out[[1]])==0){
			profiles[[i]]<-"error"
        }else{	
			out2<-matrix(ncol=2,nrow=length(out[[1]]))
			out2[,1]<-out[[1]]
			out2[,2]<-out[[2]]
			colnames(out2)<-c("m/z","abundance")
			profiles[[i]]<-out2
			if(plotit==TRUE){
				plot(out2[,1],out2[,2],type="h",xlab="m/z",ylab="Relative abundance",main=names(pattern)[i])
			}
		}
    }
	names(profiles) <- names(pattern)
    if(verbose) message(" done.")
    ############################################################################
    # (3) output ###############################################################
    return(profiles) 
    ############################################################################
    
}
